// Desktop-only pure import modules, pinned to the shipping reference. This
// bundle never loads Sync, settings, Electron, filesystem or account modules.
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import {execFileSync} from 'node:child_process';
import {fileURLToPath} from 'node:url';
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'../..');
const runner=path.join(root,'chromium/blanc/services/sync_runner');
const SHIMS=['crypto','url','desktop-import','desktop-import-buffer'];
const EXTERNAL={'crypto':'crypto','node:crypto':'crypto','node:url':'url','url':'url'};
const literal=v=>JSON.stringify(v).replace(/[<>\u2028\u2029]/g,c=>`\\u${c.charCodeAt(0).toString(16).padStart(4,'0')}`);
export function importBundle(tag){
 const show=file=>{try{return execFileSync('git',['-C',root,'show',`${tag}:${file}`],{encoding:'utf8',maxBuffer:4e6,stdio:['ignore','pipe','ignore']});}catch{return null;}};
 const modules=new Map(),maps=new Map();
 function visit(target){
  const id=[target,`${target}.js`,`${target}.json`].find(f=>modules.has(f)||show(f)!=null);
  if(!id)throw Error('Missing import dependency: '+target);
  if(modules.has(id))return id;
  const source=show(id);modules.set(id,source);const map={};maps.set(id,map);
  for(const [,name] of source.matchAll(/require\(\s*['"]([^'"]+)['"]\s*\)/g)){
   if(name.startsWith('.'))map[name]=visit(path.posix.normalize(path.posix.join(path.posix.dirname(id),name)));
   else if(EXTERNAL[name])map[name]=`shim:${EXTERNAL[name]}`;
   else throw Error('Unaudited import dependency: '+name+' in '+id);
  }
  return id;
 }
 for(const name of ['chromium-session','tab-import-session','tab-import-organizer','tab-import-apply','arc-sidebar'])visit(`src/main/${name}.js`);
 const shim=name=>fs.readFileSync(path.join(runner,'shims',name+'.js'),'utf8');
 const entries=SHIMS.map(name=>`${literal('shim:'+name)}:[function(module,exports,require){\n${shim(name)}\n},{}]`);
 for(const [id,source] of [...modules].sort()){
  const prefix=id==='src/main/chromium-session.js'?"const Buffer=__require('shim:desktop-import-buffer');\n":'';
  entries.push(`${literal(id)}:[function(module,exports,require){\n${prefix}${source}\n},${literal(maps.get(id))}]`);
 }
 return `// Generated by chromium/tools/build-import-bundle.mjs from ${tag}. Don't edit.
${shim('prelude')}
(function(g){'use strict';const M={${entries.join(',\n')}};const C={};
function load(id){if(C[id])return C[id].exports;const e=M[id];if(!e)throw Error('no module '+id);const m=C[id]={exports:{}};
e[0](m,m.exports,r=>{const t=e[1][r];if(!t)throw Error('no require '+r+' in '+id);return load(t)});return m.exports}
g.__require=load;})(globalThis);
globalThis.__call=(method,argsJson,done)=>{try{if(method!=='desktop.import')throw Error('forbidden');
done(true,JSON.stringify(__require('shim:desktop-import')(...JSON.parse(argsJson))));}catch(error){done(false,String(error.message||error));}};
`;
}
export const hashImport=text=>crypto.createHash('sha256').update(text).digest('hex');
if(process.argv[1]===fileURLToPath(import.meta.url)){
 const tag=(t=>t.bundleTag??t.shippingTag)(JSON.parse(fs.readFileSync(path.join(root,'chromium/tracker.json'))));
 const text=importBundle(tag),hash=hashImport(text);
 const files={'generated/import-bundle.js':text,'import_bundle_hash.h':`// Generated by chromium/tools/build-import-bundle.mjs. Don't edit.\n#ifndef BLANC_SERVICES_SYNC_RUNNER_IMPORT_BUNDLE_HASH_H_\n#define BLANC_SERVICES_SYNC_RUNNER_IMPORT_BUNDLE_HASH_H_\nnamespace blanc { inline constexpr char kBlancImportBundleSha256[] = "${hash}"; }\n#endif\n`};
 for(const [name,bytes] of Object.entries(files)){const file=path.join(runner,name);if(process.argv.includes('--check')){if(fs.readFileSync(file,'utf8')!==bytes)throw Error('Import bundle is stale: '+name);}else fs.writeFileSync(file,bytes);}
 console.log(`${tag}: import ${text.length} bytes, ${hash}`);
}
